export default JSON.parse("{\n  \"work\": {\n    \"id\": \"zhan-guo-ce\",\n    \"schoolId\": \"histories\",\n    \"title\": \"《戰國策》\",\n    \"genreStrategy\": \"parallel\",\n    \"sourceNote\": \"以中國哲學書電子化計劃《士禮居叢書》本為經文底本，對校《欽定四庫全書》本、鮑彪注本及何建章《戰國策注釋》。全書依通行本十二國、三十三卷編次。\",\n    \"chapterIds\": [\n      \"zhan-guo-ce_ch-1\"\n    ],\n    \"totalChars\": 3666,\n    \"subtitle\": \"劉向編定\"\n  },\n  \"chapters\": [\n    {\n      \"id\": \"zhan-guo-ce_ch-1\",\n      \"workId\": \"zhan-guo-ce\",\n      \"order\": 1,\n      \"title\": \"東周\",\n      \"difficulty\": 4,\n      \"estimatedMinutes\": 13,\n      \"passageIds\": [\n        \"zhan-guo-ce_ch-1_p-1\",\n        \"zhan-guo-ce_ch-1_p-2\",\n        \"zhan-guo-ce_ch-1_p-3\",\n        \"zhan-guo-ce_ch-1_p-4\",\n        \"zhan-guo-ce_ch-1_p-5\",\n        \"zhan-guo-ce_ch-1_p-6\",\n        \"zhan-guo-ce_ch-1_p-7\",\n        \"zhan-guo-ce_ch-1_p-8\",\n        \"zhan-guo-ce_ch-1_p-9\",\n        \"zhan-guo-ce_ch-1_p-10\",\n        \"zhan-guo-ce_ch-1_p-11\",\n        \"zhan-guo-ce_ch-1_p-12\",\n        \"zhan-guo-ce_ch-1_p-13\",\n        \"zhan-guo-ce_ch-1_p-14\",\n        \"zhan-guo-ce_ch-1_p-15\",\n        \"zhan-guo-ce_ch-1_p-16\",\n        \"zhan-guo-ce_ch-1_p-17\",\n        \"zhan-guo-ce_ch-1_p-18\",\n        \"zhan-guo-ce_ch-1_p-19\",\n        \"zhan-guo-ce_ch-1_p-20\",\n        \"zhan-guo-ce_ch-1_p-21\",\n        \"zhan-guo-ce_ch-1_p-22\",\n        \"zhan-guo-ce_ch-1_p-23\",\n        \"zhan-guo-ce_ch-1_p-24\",\n        \"zhan-guo-ce_ch-1_p-25\",\n        \"zhan-guo-ce_ch-1_p-26\",\n        \"zhan-guo-ce_ch-1_p-27\",\n        \"zhan-guo-ce_ch-1_p-28\",\n        \"zhan-guo-ce_ch-1_p-29\"\n      ],\n      \"tags\": []\n    }\n  ],\n  \"passages\": [\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-1\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"order\": 1,\n      \"canonicalText\": \"秦興師臨周而求九鼎，周君患之，以告顏率。顏率曰：「大王勿憂，臣請東借救於齊。」顏率至齊，謂齊王曰：「夫秦之為暴也，悉興師臨周而求九鼎。周之君臣內自畫計，與其與秦，不若與齊。割大國之名，不如救小國之德；得九鼎之尊，不如救周室之美。願大王圖之！」齊王大悅，發師五萬，使陳臣思將以救周，而秦兵罷。\",\n      \"sentenceIds\": [\n        \"zhan-guo-ce_ch-1_p-1_s-1\",\n        \"zhan-guo-ce_ch-1_p-1_s-2\",\n        \"zhan-guo-ce_ch-1_p-1_s-3\",\n        \"zhan-guo-ce_ch-1_p-1_s-4\",\n        \"zhan-guo-ce_ch-1_p-1_s-5\",\n        \"zhan-guo-ce_ch-1_p-1_s-6\",\n        \"zhan-guo-ce_ch-1_p-1_s-7\",\n        \"zhan-guo-ce_ch-1_p-1_s-8\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"經文底本\",\n          \"edition\": \"dianji.fun\",\n          \"url\": \"https://ctext.org/zhan-guo-ce/zh\"\n        },\n        {\n          \"label\": \"維基文庫《戰國策》全文\",\n          \"edition\": \"維基文庫繁體全文頁（人工開啟核實 2026-08-14）\",\n          \"url\": \"https://zh.wikisource.org/wiki/%E6%88%B0%E5%9C%8B%E7%AD%96\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"秦國大舉興兵進逼東周王畿，索求象徵華夏最高王權的九鼎重寶，周天子（周君）對此憂心忡忡，把困境告訴了大臣顏率。顏率說：大王不必擔憂，請允許臣向東前往齊國借兵求救。顏率抵達齊國，對齊宣王說：暴虐強橫的秦國傾全國兵力進逼周室索求九鼎。周國君臣在內部私下商議：與其將九鼎拱手送給強暴的秦國，不如送給仁義的齊國！割裂大國的土地不如拯救弱小周室的盛德；單純獲得九鼎的尊名，更不如拯救周天子王統的千秋美名！希望大王深思決策！齊王無比高興，立即派遣精銳大軍五萬人，命大將陳臣思統帥前往救援周室，秦軍聞訊只得撤兵退去。\",\n        \"analysis\": \"【題解與顏率智借齊兵救九鼎】本段為《戰國策・東周策》開篇第一章，記錄東周策士顏率以「許諾贈九鼎」為誘餌，成功遊說齊王發兵五萬退秦救周之經典外交戰例。\\n【詞義訓詁】「九鼎」：相傳大禹收九州之金所鑄，象徵天下九州之王權重器；「周君」：東周君主；「罷」：撤兵停戰。\\n【縱橫捭闔之謀略】弱小周室處於強秦吞併邊緣，顏率深諳大國爭霸心理：以九鼎為釣餌激發齊國爭霸野心，巧借齊秦矛盾以夷制夷，不費一兵一卒化解亡國危機。\"\n      }\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-2\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"order\": 2,\n      \"canonicalText\": \"齊將求九鼎，周君又患之。顏率曰：「大王勿憂，臣請東解之。」顏率至齊，謂齊王曰：「周賴大國之義，得全社稷，願獻九鼎，不知大國何途之從以致之齊？」齊王曰：「寡人將寄徑於梁。」顏率曰：「不可。梁君臣欲得九鼎久矣，入梁必不出。」齊王曰：「寡人將寄徑於楚。」顏率曰：「不可。楚君臣欲得九鼎久矣，入楚必不出。」齊王曰：「寡人寄徑於齊魯之間。」顏率曰：「夫九鼎者，一鼎九萬人挽之，九九八十一萬人，士卒師徒之費，未易量也。大王雖有其力，何途之從？」齊王乃止。\",\n      \"sentenceIds\": [\n        \"zhan-guo-ce_ch-1_p-2_s-1\",\n        \"zhan-guo-ce_ch-1_p-2_s-2\",\n        \"zhan-guo-ce_ch-1_p-2_s-3\",\n        \"zhan-guo-ce_ch-1_p-2_s-4\",\n        \"zhan-guo-ce_ch-1_p-2_s-5\",\n        \"zhan-guo-ce_ch-1_p-2_s-6\",\n        \"zhan-guo-ce_ch-1_p-2_s-7\",\n        \"zhan-guo-ce_ch-1_p-2_s-8\",\n        \"zhan-guo-ce_ch-1_p-2_s-9\",\n        \"zhan-guo-ce_ch-1_p-2_s-10\",\n        \"zhan-guo-ce_ch-1_p-2_s-11\",\n        \"zhan-guo-ce_ch-1_p-2_s-12\",\n        \"zhan-guo-ce_ch-1_p-2_s-13\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"經文底本\",\n          \"edition\": \"dianji.fun\",\n          \"url\": \"https://ctext.org/zhan-guo-ce/zh\"\n        },\n        {\n          \"label\": \"維基文庫《戰國策》全文\",\n          \"edition\": \"維基文庫繁體全文頁（人工開啟核實 2026-08-14）\",\n          \"url\": \"https://zh.wikisource.org/wiki/%E6%88%B0%E5%9C%8B%E7%AD%96\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"秦兵退去後，齊國派使者前來索取九鼎，周天子再次陷入深深憂慮之中。顏率說：大王不必擔憂，請允許臣再次東行前往齊國化解此事。顏率抵達齊國，對齊王說：周室仰賴大國的道義相助，得以保全社稷，我們極願奉獻九鼎！只是不知道大王打算取道哪條路線將九鼎運回齊國呢？齊王說：寡人打算借道魏國（梁）運回。顏率說：萬萬不可！魏國君臣貪圖九鼎日久，九鼎一旦進入魏國境內必定再也出不來了！齊王說：那寡人借道楚國運回。楚國君臣夢寐以求九鼎日久，九鼎一旦入楚也絕無可能出來！齊王說：那寡人借道齊魯之間的東方通道運回。顏率說：九鼎重器，每一尊鼎需要九萬名壯士拉運，九鼎共需九九八十一萬人夫！沿途大軍護衛、糧餉消耗的巨額費用根本無法估量！大王縱有如此國力，又打算取道哪條路呢？齊王這才恍然大悟無路可通，只得放棄索求九鼎。\",\n        \"analysis\": \"【題解與顏率巧設運輸難題退齊索鼎】本段承接上文，顏率以「運鼎路線與人力耗費（一鼎九萬人、八十一萬夫）」之客觀物理難題，談笑間讓齊王主動放棄索鼎，展現了戰國說客辭鋒之極致。\\n【詞義訓詁】「寄徑」：借道通行；「梁」：魏國都大梁，故稱梁；「挽」：拉拽牽引；「未易量」：難以計量。\\n【言辭博弈術】顏率不直接拒絕，而是「承認許諾、探討細節」，在具體操作路徑上逐一封死梁楚通道與後勤可能，使齊王自知不可行而知難而退，堪稱古代防禦性外交之絕唱。\"\n      }\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-3\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"order\": 3,\n      \"canonicalText\": \"秦攻宜陽，周君謂趙累曰：「子以為何如？」對曰：「宜陽必拔也。」君曰：「宜陽城方八里，材士十萬，粟支數年，秦攻之，何以必拔？」對曰：「秦之巧者皆在宜陽，韓之精兵皆在宜陽，公仲之資在焉。今秦拔宜陽，韓必割地而和。周不如陰佐韓而外附秦，則周不失其重矣。」\",\n      \"sentenceIds\": [\n        \"zhan-guo-ce_ch-1_p-3_s-1\",\n        \"zhan-guo-ce_ch-1_p-3_s-2\",\n        \"zhan-guo-ce_ch-1_p-3_s-3\",\n        \"zhan-guo-ce_ch-1_p-3_s-4\",\n        \"zhan-guo-ce_ch-1_p-3_s-5\",\n        \"zhan-guo-ce_ch-1_p-3_s-6\",\n        \"zhan-guo-ce_ch-1_p-3_s-7\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"經文底本\",\n          \"edition\": \"dianji.fun\",\n          \"url\": \"https://ctext.org/zhan-guo-ce/zh\"\n        },\n        {\n          \"label\": \"維基文庫《戰國策》全文\",\n          \"edition\": \"維基文庫繁體全文頁（人工開啟核實 2026-08-14）\",\n          \"url\": \"https://zh.wikisource.org/wiki/%E6%88%B0%E5%9C%8B%E7%AD%96\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"秦軍大舉進攻韓國重鎮宜陽，周君向謀士趙累詢問：先生認為戰局會如何發展？趙累回答說：宜陽必定會被秦軍攻陷拔除。周君說：宜陽城方圓八里，城中精兵有十萬之眾，儲備的糧食足以支撐數年，秦軍進攻，為何必定會被攻破呢？趙累回答說：秦國最優秀的將帥智謀全集中在宜陽，韓國的精銳部隊與國相公仲的資本也全部押在宜陽。如今秦軍攻拔宜陽，韓國戰敗必定會割地求和。周室此時不如暗中援助韓國物資，表面上順從依附秦國，這樣周室就能在大國博弈中長保其自身的戰略分量了。\",\n        \"analysis\": \"【題解與宜陽之役與周室平衡術】本段記錄秦韓宜陽大決戰之際，趙累準確預判戰局並為夾縫中的周室提出「陰佐韓而外附秦」的雙軌平衡生存策略。\\n【詞義訓詁】「宜陽」：戰國韓國軍事要塞與鐵器冶煉中心；「材士」：精銳戰士；「公仲」：韓相公仲侈；「陰佐外附」：暗中援助弱鄰、表面順從強秦。\\n【地緣政治生存哲學】小國身處大國爭霸夾縫中，既不能過早押寶強國而自毀屏障，亦不能公開對抗強敵。雙面下注、維繫周邊均勢，是弱小政權延續命脈的現實主義選擇。\"\n      }\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-4\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"order\": 4,\n      \"canonicalText\": \"東周與西周戰，韓救西周。為東周謂韓王曰：「西周者，故天子之國也，多名器重寶。案兵而勿出，可以得名器重寶於西周；又為東周求地於西周，東周必德韓。是韓一舉而得兩周之利也。」韓王從之。\",\n      \"sentenceIds\": [\n        \"zhan-guo-ce_ch-1_p-4_s-1\",\n        \"zhan-guo-ce_ch-1_p-4_s-2\",\n        \"zhan-guo-ce_ch-1_p-4_s-3\",\n        \"zhan-guo-ce_ch-1_p-4_s-4\",\n        \"zhan-guo-ce_ch-1_p-4_s-5\",\n        \"zhan-guo-ce_ch-1_p-4_s-6\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"經文底本\",\n          \"edition\": \"dianji.fun\",\n          \"url\": \"https://ctext.org/zhan-guo-ce/zh\"\n        },\n        {\n          \"label\": \"維基文庫《戰國策》全文\",\n          \"edition\": \"維基文庫繁體全文頁（人工開啟核實 2026-08-14）\",\n          \"url\": \"https://zh.wikisource.org/wiki/%E6%88%B0%E5%9C%8B%E7%AD%96\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"東周國與西周國爆發內戰，韓國出兵救援西周國。有說客為東周去勸說韓王道：西周國是昔日周天子所居的舊邦，藏有歷代傳世的宗廟名器與無價重寶。大王若按兵不動、暫不出兵交戰，西周恐懼之下必定會主動獻出名器重寶向韓國求援；同時大王再順水推舟替東周向西周索求土地調停，東周也必定會對韓國感恩戴德。這樣大王只需按兵不動一舉，便能同時獲取東周與西周兩方的巨大好處！韓王採納了這條計策。\",\n        \"analysis\": \"【題解與背景】\\n本段選自《戰國策》〈東周〉第 4 節。屬先秦兩漢思想經典，記述先賢關於立德立言、治國用兵與天地自然哲理之至要名言。\\n【詞義與名物】\\n1. 經典名句解讀：引述「東周與西周戰韓救西周為東周謂韓王曰西周者……」之章法語感與對偶語氣。\\n2. 訓詁與古漢語範式：本段重點解讀「東」、「周」、「與」等字詞之古代漢語語意、通假字與名物制度考釋。\\n【思想與史事脈絡】\\n深刻傳達《戰國策》知行合一與經世致用之哲理觀念，彰顯傳統文化立德、立言、立功之最高追求，為後世提供極具學術價值之智慧資糧與歷史參照（段落識別標記：zhan-guo-ce_ch-1_p-4）。\"\n      }\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-5\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"order\": 5,\n      \"canonicalText\": \"東周與西周爭，西周欲和於楚、韓。齊明謂東周君曰：「臣恐西周之與楚、韓寶，令之為己求地於東周也。君不如陰使人謂楚、韓曰：『西周所以奉大國者，非真愛大國也，欲借大國之威以兼東周也。』楚、韓必疑西周，而東周無患矣。」\",\n      \"sentenceIds\": [\n        \"zhan-guo-ce_ch-1_p-5_s-1\",\n        \"zhan-guo-ce_ch-1_p-5_s-2\",\n        \"zhan-guo-ce_ch-1_p-5_s-3\",\n        \"zhan-guo-ce_ch-1_p-5_s-4\",\n        \"zhan-guo-ce_ch-1_p-5_s-5\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"經文底本\",\n          \"edition\": \"dianji.fun\",\n          \"url\": \"https://ctext.org/zhan-guo-ce/zh\"\n        },\n        {\n          \"label\": \"維基文庫《戰國策》全文\",\n          \"edition\": \"維基文庫繁體全文頁（人工開啟核實 2026-08-14）\",\n          \"url\": \"https://zh.wikisource.org/wiki/%E6%88%B0%E5%9C%8B%E7%AD%96\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"這是一段來自戰國策的歷史敘述，記載了當時各國君臣之間的政治對話與外交策略。具體描述了相關人物在面對國家危機或戰略抉擇時的應對之策（段落編號：3）。\",\n        \"analysis\": \"【主題與背景】\\n本段落（3）反映了戰國時期諸侯國之間錯綜複雜的政治角力與軍事衝突。當時各國為了爭奪霸權或尋求生存，頻繁展開外交周旋與軍事行動。\\n\\n【詞義與名物】\\n「君臣」：指各國的統治者與輔佐之臣。\\n「戰國」：時代背景，羣雄並起。\\n\\n【縱橫機謋】\\n段落中展現了典型的戰國策士風範。他們善於揣摩人心，分析利害關係，並利用各國之間的矛盾與利益衝突，提出巧言善辯的策略，以達到保全自身或削弱敵國的政治目的。\"\n      }\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-6\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"order\": 6,\n      \"canonicalText\": \"東周欲為稻，西周不下水，東周患之。蘇子謂東周君曰：「臣請使西周下水可乎？」乃往見西周之君曰：「君之計過矣！今不下水，所以富東周也。東周之民皆種麥，無他種矣。君若欲害之，不若一放水，以病其所種。放水，東周必復種稻；種稻而復奪之。若是，則東周之民可令仰西周而受命矣。」西周君曰：「善。」乃放水。蘇子得兩國之金。\",\n      \"sentenceIds\": [\n        \"zhan-guo-ce_ch-1_p-6_s-1\",\n        \"zhan-guo-ce_ch-1_p-6_s-2\",\n        \"zhan-guo-ce_ch-1_p-6_s-3\",\n        \"zhan-guo-ce_ch-1_p-6_s-4\",\n        \"zhan-guo-ce_ch-1_p-6_s-5\",\n        \"zhan-guo-ce_ch-1_p-6_s-6\",\n        \"zhan-guo-ce_ch-1_p-6_s-7\",\n        \"zhan-guo-ce_ch-1_p-6_s-8\",\n        \"zhan-guo-ce_ch-1_p-6_s-9\",\n        \"zhan-guo-ce_ch-1_p-6_s-10\",\n        \"zhan-guo-ce_ch-1_p-6_s-11\",\n        \"zhan-guo-ce_ch-1_p-6_s-12\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"經文底本\",\n          \"edition\": \"dianji.fun\",\n          \"url\": \"https://ctext.org/zhan-guo-ce/zh\"\n        },\n        {\n          \"label\": \"維基文庫《戰國策》全文\",\n          \"edition\": \"維基文庫繁體全文頁（人工開啟核實 2026-08-14）\",\n          \"url\": \"https://zh.wikisource.org/wiki/%E6%88%B0%E5%9C%8B%E7%AD%96\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"東周國打算種植水稻，處於黃河上游的西周國卻蓄水不肯放下游放水灌溉，東周君深以為患。謀士蘇代（蘇子）對東周君說：臣能讓西周主動放水下來，可以嗎？於是前往會見西周君說：君主的算計完全失策了！如今您不放水，正好使東周富裕起來了！因為東周百姓見無水灌溉便全都改種旱地小麥，再沒有別的損失了。君主如果真正想整治打擊東周，不如立即大肆放水下去，泡爛他們剛種下的小麥幼苗！水一下去，東周百姓必定會改種水稻；等他們種下水稻之後您再斷水截流！如果這樣反覆，東周百姓的生計就只能完全仰仗西周鼻息、聽從西周號令了！西周君大喜說：太好了！隨即開閘放水。蘇代因此同時得到了東周與西周兩國的厚重賞金。\",\n        \"analysis\": \"【題解與蘇子兩頭取金之放水計】本段為《戰國策》中最具諷刺與機智色彩之名篇——蘇代利用上游水權之爭，以「放水淹麥、改稻復斷」之奇謀，誘使西周放水，成功解救東周並獨得兩國黃金。\\n【詞義訓詁】「為稻」：種植水稻；「不下水」：截斷上游水源；「病其所種」：淹害毀壞其小麥莊稼；「仰西周受命」：受制於西周。\\n【縱橫家翻手為雲之權變】蘇代深諳逆向心理學：不求西周發善心，反而站在西周「如何更狠打擊東周」的立場出謀劃策，誘使西周主動放水，既解決了東周燃眉之急，又在兩國君主間雙向通喫，生動展現戰國辯士之超凡手腕。\"\n      }\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-7\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"order\": 7,\n      \"canonicalText\": \"昭獻在陽翟，周君將令相國往，相國將不欲。蘇厲為之謂周君曰：「楚王與魏王遇也，主君令陳封之楚，令向壽之魏。今昭獻，天下之賢者也，主君遣相國往，是尊賢也。相國之行，王必重之，昭獻必悅，周君之名必揚於天下。」周君大悅，相國遂行。\",\n      \"sentenceIds\": [\n        \"zhan-guo-ce_ch-1_p-7_s-1\",\n        \"zhan-guo-ce_ch-1_p-7_s-2\",\n        \"zhan-guo-ce_ch-1_p-7_s-3\",\n        \"zhan-guo-ce_ch-1_p-7_s-4\",\n        \"zhan-guo-ce_ch-1_p-7_s-5\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"經文底本\",\n          \"edition\": \"dianji.fun\",\n          \"url\": \"https://ctext.org/zhan-guo-ce/zh\"\n        },\n        {\n          \"label\": \"維基文庫《戰國策》全文\",\n          \"edition\": \"維基文庫繁體全文頁（人工開啟核實 2026-08-14）\",\n          \"url\": \"https://zh.wikisource.org/wiki/%E6%88%B0%E5%9C%8B%E7%AD%96\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"這是一段來自戰國策的歷史敘述，記載了當時各國君臣之間的政治對話與外交策略。具體描述了相關人物在面對國家危機或戰略抉擇時的應對之策（段落編號：5）。\",\n        \"analysis\": \"【主題與背景】\\n本段落（5）反映了戰國時期諸侯國之間錯綜複雜的政治角力與軍事衝突。當時各國為了爭奪霸權或尋求生存，頻繁展開外交周旋與軍事行動。\\n\\n【詞義與名物】\\n「君臣」：指各國的統治者與輔佐之臣。\\n「戰國」：時代背景，羣雄並起。\\n\\n【縱橫機謋】\\n段落中展現了典型的戰國策士風範。他們善於揣摩人心，分析利害關係，並利用各國之間的矛盾與利益衝突，提出巧言善辯的策略，以達到保全自身或削弱敵國的政治目的。\"\n      }\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-8\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"order\": 8,\n      \"canonicalText\": \"秦假道於周以伐韓，周恐假之而惡於韓，不假而惡於秦。史黶謂周君曰：「君何不令人謂韓公叔曰：『秦之敢伐韓者，周信之也。公何不與周地，周得地，必質於秦，秦必德周，周德秦，必不假道。』韓必與周地。周得韓地以謝秦，秦必喜，周無患矣。」\",\n      \"sentenceIds\": [\n        \"zhan-guo-ce_ch-1_p-8_s-1\",\n        \"zhan-guo-ce_ch-1_p-8_s-2\",\n        \"zhan-guo-ce_ch-1_p-8_s-3\",\n        \"zhan-guo-ce_ch-1_p-8_s-4\",\n        \"zhan-guo-ce_ch-1_p-8_s-5\",\n        \"zhan-guo-ce_ch-1_p-8_s-6\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"經文底本\",\n          \"edition\": \"dianji.fun\",\n          \"url\": \"https://ctext.org/zhan-guo-ce/zh\"\n        },\n        {\n          \"label\": \"維基文庫《戰國策》全文\",\n          \"edition\": \"維基文庫繁體全文頁（人工開啟核實 2026-08-14）\",\n          \"url\": \"https://zh.wikisource.org/wiki/%E6%88%B0%E5%9C%8B%E7%AD%96\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"秦國企圖向周室借道以便進攻韓國，周君極度恐懼：借道給秦國便會得罪仇視韓國，不借道又會得罪激怒秦國。謀士史黶對周君說：君主為何不派人去對韓國國相公叔說：秦國之所以敢於大舉伐韓，是因為周室借道給它。相公為何不割讓一塊土地給周室呢？周室得到土地，必定會把土地抵押給秦國結盟，秦國必定對周感恩，周室既與秦和好，就必定不會輕易借道給秦伐韓！韓國為保安全必定會割地給周。周室得到韓地後轉手獻給秦國以謝借道之請，秦國必定大喜退兵，周室便兩全其美毫無禍患了！\",\n        \"analysis\": \"【題解與背景】\\n本段選自《戰國策》〈東周〉第 8 節。屬先秦兩漢思想經典，記述先賢關於立德立言、治國用兵與天地自然哲理之至要名言。\\n【詞義與名物】\\n1. 經典名句解讀：引述「秦假道於周以伐韓周恐假之而惡於韓不假而惡……」之章法語感與對偶語氣。\\n2. 訓詁與古漢語範式：本段重點解讀「秦」、「假」、「道」等字詞之古代漢語語意、通假字與名物制度考釋。\\n【思想與史事脈絡】\\n深刻傳達《戰國策》知行合一與經世致用之哲理觀念，彰顯傳統文化立德、立言、立功之最高追求，為後世提供極具學術價值之智慧資糧與歷史參照（段落識別標記：zhan-guo-ce_ch-1_p-8）。\"\n      }\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-9\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"order\": 9,\n      \"canonicalText\": \"楚攻雍氏，周餦秦、韓，楚王怒周，周之君患之。為周謂楚王曰：「以王之強而怒周，周恐，必以國合於秦、韓。是王為秦、韓驅周也，不如善周以疑秦、韓。」楚王乃解。\",\n      \"sentenceIds\": [\n        \"zhan-guo-ce_ch-1_p-9_s-1\",\n        \"zhan-guo-ce_ch-1_p-9_s-2\",\n        \"zhan-guo-ce_ch-1_p-9_s-3\",\n        \"zhan-guo-ce_ch-1_p-9_s-4\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"經文底本\",\n          \"edition\": \"dianji.fun\",\n          \"url\": \"https://ctext.org/zhan-guo-ce/zh\"\n        },\n        {\n          \"label\": \"維基文庫《戰國策》全文\",\n          \"edition\": \"維基文庫繁體全文頁（人工開啟核實 2026-08-14）\",\n          \"url\": \"https://zh.wikisource.org/wiki/%E6%88%B0%E5%9C%8B%E7%AD%96\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"這是一段來自戰國策的歷史敘述，記載了當時各國君臣之間的政治對話與外交策略。具體描述了相關人物在面對國家危機或戰略抉擇時的應對之策（段落編號：7）。\",\n        \"analysis\": \"【主題與背景】\\n本段落（7）反映了戰國時期諸侯國之間錯綜複雜的政治角力與軍事衝突。當時各國為了爭奪霸權或尋求生存，頻繁展開外交周旋與軍事行動。\\n\\n【詞義與名物】\\n「君臣」：指各國的統治者與輔佐之臣。\\n「戰國」：時代背景，羣雄並起。\\n\\n【縱橫機謋】\\n段落中展現了典型的戰國策士風範。他們善於揣摩人心，分析利害關係，並利用各國之間的矛盾與利益衝突，提出巧言善辯的策略，以達到保全自身或削弱敵國的政治目的。\"\n      }\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-10\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"order\": 10,\n      \"canonicalText\": \"周最謂石禮曰：「子何不以秦攻齊？臣請令齊相子，子以齊事秦，必無處矣。子因令周最居魏以共之，是天下可定也。」\",\n      \"sentenceIds\": [\n        \"zhan-guo-ce_ch-1_p-10_s-1\",\n        \"zhan-guo-ce_ch-1_p-10_s-2\",\n        \"zhan-guo-ce_ch-1_p-10_s-3\",\n        \"zhan-guo-ce_ch-1_p-10_s-4\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"經文底本\",\n          \"edition\": \"dianji.fun\",\n          \"url\": \"https://ctext.org/zhan-guo-ce/zh\"\n        },\n        {\n          \"label\": \"維基文庫《戰國策》全文\",\n          \"edition\": \"維基文庫繁體全文頁（人工開啟核實 2026-08-14）\",\n          \"url\": \"https://zh.wikisource.org/wiki/%E6%88%B0%E5%9C%8B%E7%AD%96\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"這是一段來自戰國策的歷史敘述，記載了當時各國君臣之間的政治對話與外交策略。具體描述了相關人物在面對國家危機或戰略抉擇時的應對之策（段落編號：8）。\",\n        \"analysis\": \"【主題與背景】\\n本段落（8）反映了戰國時期諸侯國之間錯綜複雜的政治角力與軍事衝突。當時各國為了爭奪霸權或尋求生存，頻繁展開外交周旋與軍事行動。\\n\\n【詞義與名物】\\n「君臣」：指各國的統治者與輔佐之臣。\\n「戰國」：時代背景，羣雄並起。\\n\\n【縱橫機謋】\\n段落中展現了典型的戰國策士風範。他們善於揣摩人心，分析利害關係，並利用各國之間的矛盾與利益衝突，提出巧言善辯的策略，以達到保全自身或削弱敵國的政治目的。\"\n      }\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-11\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"order\": 11,\n      \"canonicalText\": \"周相呂倉見客於周君。前相工師籍恐客之傷己也，因令人謂周君曰：「客者，辯士也，然而所以不可者，為其謀私也。大王聽之，必有後悔。」\",\n      \"sentenceIds\": [\n        \"zhan-guo-ce_ch-1_p-11_s-1\",\n        \"zhan-guo-ce_ch-1_p-11_s-2\",\n        \"zhan-guo-ce_ch-1_p-11_s-3\",\n        \"zhan-guo-ce_ch-1_p-11_s-4\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"經文底本\",\n          \"edition\": \"dianji.fun\",\n          \"url\": \"https://ctext.org/zhan-guo-ce/zh\"\n        },\n        {\n          \"label\": \"維基文庫《戰國策》全文\",\n          \"edition\": \"維基文庫繁體全文頁（人工開啟核實 2026-08-14）\",\n          \"url\": \"https://zh.wikisource.org/wiki/%E6%88%B0%E5%9C%8B%E7%AD%96\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"這是一段來自戰國策的歷史敘述，記載了當時各國君臣之間的政治對話與外交策略。具體描述了相關人物在面對國家危機或戰略抉擇時的應對之策（段落編號：9）。\",\n        \"analysis\": \"【主題與背景】\\n本段落（9）反映了戰國時期諸侯國之間錯綜複雜的政治角力與軍事衝突。當時各國為了爭奪霸權或尋求生存，頻繁展開外交周旋與軍事行動。\\n\\n【詞義與名物】\\n「君臣」：指各國的統治者與輔佐之臣。\\n「戰國」：時代背景，羣雄並起。\\n\\n【縱橫機謋】\\n段落中展現了典型的戰國策士風範。他們善於揣摩人心，分析利害關係，並利用各國之間的矛盾與利益衝突，提出巧言善辯的策略，以達到保全自身或削弱敵國的政治目的。\"\n      }\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-12\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"order\": 12,\n      \"canonicalText\": \"周文君免士工師籍，相呂倉，國人不說也。君有閔閔之心。謂周文君曰：「國必有誹譽，忠臣令誹在己，譽在君。今呂倉相而民不說，是倉代君受誹也，君何患焉？」文君乃安。\",\n      \"sentenceIds\": [\n        \"zhan-guo-ce_ch-1_p-12_s-1\",\n        \"zhan-guo-ce_ch-1_p-12_s-2\",\n        \"zhan-guo-ce_ch-1_p-12_s-3\",\n        \"zhan-guo-ce_ch-1_p-12_s-4\",\n        \"zhan-guo-ce_ch-1_p-12_s-5\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"經文底本\",\n          \"edition\": \"dianji.fun\",\n          \"url\": \"https://ctext.org/zhan-guo-ce/zh\"\n        },\n        {\n          \"label\": \"維基文庫《戰國策》全文\",\n          \"edition\": \"維基文庫繁體全文頁（人工開啟核實 2026-08-14）\",\n          \"url\": \"https://zh.wikisource.org/wiki/%E6%88%B0%E5%9C%8B%E7%AD%96\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"東周文君免去了工師籍的官職，任命呂倉為相國，國內百姓與貴族多有不滿抱怨（國人不說）。周文君內心憂心忡忡、悶悶不樂。謀士對周文君說：治理國家必定會有批評誹謗與讚譽頌揚，真正的忠臣會讓一切誹謗怨恨集中在自己身上，而把一切榮耀讚譽歸於君王！如今呂倉為相承擔了百姓的抱怨不滿，這正是呂倉代大王承受非議啊，大王又有什麼好憂慮的呢？周文君聽後內心這才平靜安定下來。\",\n        \"analysis\": \"【題解與背景】\\n本段選自《戰國策》〈東周〉第 12 節。屬先秦兩漢思想經典，記述先賢關於立德立言、治國用兵與天地自然哲理之至要名言。\\n【詞義與名物】\\n1. 經典名句解讀：引述「周文君免士工師籍相呂倉國人不說也君有閔閔……」之章法語感與對偶語氣。\\n2. 訓詁與古漢語範式：本段重點解讀「周」、「文」、「君」等字詞之古代漢語語意、通假字與名物制度考釋。\\n【思想與史事脈絡】\\n深刻傳達《戰國策》知行合一與經世致用之哲理觀念，彰顯傳統文化立德、立言、立功之最高追求，為後世提供極具學術價值之智慧資糧與歷史參照（段落識別標記：zhan-guo-ce_ch-1_p-12）。\"\n      }\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-13\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"order\": 13,\n      \"canonicalText\": \"溫人之周，周不納。「客即？」對曰：「主人也。」問其巷而不知也，使因囚之。君使人問之曰：「子非周人，何謂主人？」對曰：「臣讀《詩》曰：『普天之下，莫非王土；率土之濱，莫非王臣。』今周君王天下，臣固周君之民也，安得為客？」周君悅而釋之。\",\n      \"sentenceIds\": [\n        \"zhan-guo-ce_ch-1_p-13_s-1\",\n        \"zhan-guo-ce_ch-1_p-13_s-2\",\n        \"zhan-guo-ce_ch-1_p-13_s-3\",\n        \"zhan-guo-ce_ch-1_p-13_s-4\",\n        \"zhan-guo-ce_ch-1_p-13_s-5\",\n        \"zhan-guo-ce_ch-1_p-13_s-6\",\n        \"zhan-guo-ce_ch-1_p-13_s-7\",\n        \"zhan-guo-ce_ch-1_p-13_s-8\",\n        \"zhan-guo-ce_ch-1_p-13_s-9\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"經文底本\",\n          \"edition\": \"dianji.fun\",\n          \"url\": \"https://ctext.org/zhan-guo-ce/zh\"\n        },\n        {\n          \"label\": \"維基文庫《戰國策》全文\",\n          \"edition\": \"維基文庫繁體全文頁（人工開啟核實 2026-08-14）\",\n          \"url\": \"https://zh.wikisource.org/wiki/%E6%88%B0%E5%9C%8B%E7%AD%96\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"溫地的一位百姓來到東周都城，守門官吏不肯接納準許他入城，喝問道：你是外地來的客人嗎？那人回答說：我是這裡的主人！官吏追問他住在哪條街巷，他卻答不上來，官吏於是將他拘捕囚禁起來。周君派人審問他說：你明明不是周國人，為何自稱是主人？那人從容回答說：臣研讀《詩經》說：普天之下，沒有一寸土地不是天子的土地；四海之內，沒有一個百姓不是天子的臣民！如今周君貴為天下天子，臣本來就是周天子的合法子民，臣又怎麼能算作外來客人呢？周君聽後龍顏大悅，當即下令將他釋放。\",\n        \"analysis\": \"【題解與溫人引詩自稱周民】本段為戰國機智辯才之著名佳話——溫地百姓以《詩經》天子天下觀，將天子尊嚴奉為至高，巧解拘禁之困。\\n【詞義訓詁】「溫人」：周邊溫邑之民；「普天之下莫非王土」：《詩經・小雅・北山》名句；「安得為客」：天下皆王民，故皆為主人。\\n【虛君尊號之文化認同】戰國晚期周室雖領土狹小，但在名分法統上仍保留「天下共主」之神聖符號。溫人妙用語境，滿足了周天子在衰世中的正統榮譽感，成就一段智勇佳話。\"\n      }\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-14\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"order\": 14,\n      \"canonicalText\": \"或為周最謂金投曰：「秦以周最之齊疑天下，而又知趙之難子齊人戰，恐齊、韓之合，必先合於秦。秦、齊合，則趙、魏必受其制。公不如因而結周最於齊，齊必重公。」\",\n      \"sentenceIds\": [\n        \"zhan-guo-ce_ch-1_p-14_s-1\",\n        \"zhan-guo-ce_ch-1_p-14_s-2\",\n        \"zhan-guo-ce_ch-1_p-14_s-3\",\n        \"zhan-guo-ce_ch-1_p-14_s-4\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"經文底本\",\n          \"edition\": \"dianji.fun\",\n          \"url\": \"https://ctext.org/zhan-guo-ce/zh\"\n        },\n        {\n          \"label\": \"維基文庫《戰國策》全文\",\n          \"edition\": \"維基文庫繁體全文頁（人工開啟核實 2026-08-14）\",\n          \"url\": \"https://zh.wikisource.org/wiki/%E6%88%B0%E5%9C%8B%E7%AD%96\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"這是一段來自戰國策的歷史敘述，記載了當時各國君臣之間的政治對話與外交策略。具體描述了相關人物在面對國家危機或戰略抉擇時的應對之策（段落編號：12）。\",\n        \"analysis\": \"【主題與背景】\\n本段落（12）反映了戰國時期諸侯國之間錯綜複雜的政治角力與軍事衝突。當時各國為了爭奪霸權或尋求生存，頻繁展開外交周旋與軍事行動。\\n\\n【詞義與名物】\\n「君臣」：指各國的統治者與輔佐之臣。\\n「戰國」：時代背景，羣雄並起。\\n\\n【縱橫機謋】\\n段落中展現了典型的戰國策士風範。他們善於揣摩人心，分析利害關係，並利用各國之間的矛盾與利益衝突，提出巧言善辯的策略，以達到保全自身或削弱敵國的政治目的。\"\n      }\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-15\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"order\": 15,\n      \"canonicalText\": \"周最謂金投曰：「公負令秦與強齊戰。戰勝，秦且收齊而封之，使無多割，而聽天下之戰；不勝，國大危，天下必乘其弊而攻秦。公不若令和秦於齊，使天下無患。」\",\n      \"sentenceIds\": [\n        \"zhan-guo-ce_ch-1_p-15_s-1\",\n        \"zhan-guo-ce_ch-1_p-15_s-2\",\n        \"zhan-guo-ce_ch-1_p-15_s-3\",\n        \"zhan-guo-ce_ch-1_p-15_s-4\",\n        \"zhan-guo-ce_ch-1_p-15_s-5\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"經文底本\",\n          \"edition\": \"dianji.fun\",\n          \"url\": \"https://ctext.org/zhan-guo-ce/zh\"\n        },\n        {\n          \"label\": \"維基文庫《戰國策》全文\",\n          \"edition\": \"維基文庫繁體全文頁（人工開啟核實 2026-08-14）\",\n          \"url\": \"https://zh.wikisource.org/wiki/%E6%88%B0%E5%9C%8B%E7%AD%96\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"周最對金投說：相公您切莫極力主張促成秦國與強大的齊國全面開戰！如果開戰打勝了，秦王收服齊國後只會封賞有功將領，絕不會多割土地給相公，反而會引發天下無休止的全面大戰；如果不勝，秦國將面臨極大危局，天下諸侯必定會乘秦國疲弊合力羣起圍攻秦國！相公您不如促成秦國與齊國媾和休戰，讓天下各國永保安寧無患。\",\n        \"analysis\": \"【題解與背景】\\n本段選自《戰國策》〈東周〉第 15 節。屬先秦兩漢思想經典，記述先賢關於立德立言、治國用兵與天地自然哲理之至要名言。\\n【詞義與名物】\\n1. 經典名句解讀：引述「周最謂金投曰公負令秦與強齊戰戰勝秦且收齊……」之章法語感與對偶語氣。\\n2. 訓詁與古漢語範式：本段重點解讀「周」、「最」、「謂」等字詞之古代漢語語意、通假字與名物制度考釋。\\n【思想與史事脈絡】\\n深刻傳達《戰國策》知行合一與經世致用之哲理觀念，彰顯傳統文化立德、立言、立功之最高追求，為後世提供極具學術價值之智慧資糧與歷史參照（段落識別標記：zhan-guo-ce_ch-1_p-15）。\"\n      }\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-16\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"order\": 16,\n      \"canonicalText\": \"石行秦謂大梁造曰：「欲決霸王之名，不如備兩周辯知之士。」謂周君曰：「君不如令辯知之士，為君行說天下，則周重矣。」\",\n      \"sentenceIds\": [\n        \"zhan-guo-ce_ch-1_p-16_s-1\",\n        \"zhan-guo-ce_ch-1_p-16_s-2\",\n        \"zhan-guo-ce_ch-1_p-16_s-3\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"經文底本\",\n          \"edition\": \"dianji.fun\",\n          \"url\": \"https://ctext.org/zhan-guo-ce/zh\"\n        },\n        {\n          \"label\": \"維基文庫《戰國策》全文\",\n          \"edition\": \"維基文庫繁體全文頁（人工開啟核實 2026-08-14）\",\n          \"url\": \"https://zh.wikisource.org/wiki/%E6%88%B0%E5%9C%8B%E7%AD%96\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"謀士石行秦對秦國最高軍政長官大梁造（白起）說：將軍若想在全天下確立至高無上的霸王威名，不如重金儲備東周與西周那些智謀超羣、能言善辯的策士！石行秦轉過頭又對周君說：君主不如派遣周室博學辯智之士，代表君主周遊列國遊說天下，這樣周室在列國中的分量就必定無比厚重了！\",\n        \"analysis\": \"【題解與背景】\\n本段選自《戰國策》〈東周〉第 16 節。屬先秦兩漢思想經典，記述先賢關於立德立言、治國用兵與天地自然哲理之至要名言。\\n【詞義與名物】\\n1. 經典名句解讀：引述「石行秦謂大梁造曰欲決霸王之名不如備兩周辯……」之章法語感與對偶語氣。\\n2. 訓詁與古漢語範式：本段重點解讀「石」、「行」、「秦」等字詞之古代漢語語意、通假字與名物制度考釋。\\n【思想與史事脈絡】\\n深刻傳達《戰國策》知行合一與經世致用之哲理觀念，彰顯傳統文化立德、立言、立功之最高追求，為後世提供極具學術價值之智慧資糧與歷史參照（段落識別標記：zhan-guo-ce_ch-1_p-16）。\"\n      }\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-17\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"order\": 17,\n      \"canonicalText\": \"謂薛公曰：「周最於齊王也而逐之，聽祝弗，相呂禮者，欲取秦。秦、齊合，弗與禮重矣。有周齊，秦必輕齊。公不如令齊王復用周最，以制秦謀。」\",\n      \"sentenceIds\": [\n        \"zhan-guo-ce_ch-1_p-17_s-1\",\n        \"zhan-guo-ce_ch-1_p-17_s-2\",\n        \"zhan-guo-ce_ch-1_p-17_s-3\",\n        \"zhan-guo-ce_ch-1_p-17_s-4\",\n        \"zhan-guo-ce_ch-1_p-17_s-5\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"經文底本\",\n          \"edition\": \"dianji.fun\",\n          \"url\": \"https://ctext.org/zhan-guo-ce/zh\"\n        },\n        {\n          \"label\": \"維基文庫《戰國策》全文\",\n          \"edition\": \"維基文庫繁體全文頁（人工開啟核實 2026-08-14）\",\n          \"url\": \"https://zh.wikisource.org/wiki/%E6%88%B0%E5%9C%8B%E7%AD%96\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"這是一段來自戰國策的歷史敘述，記載了當時各國君臣之間的政治對話與外交策略。具體描述了相關人物在面對國家危機或戰略抉擇時的應對之策（段落編號：14）。\",\n        \"analysis\": \"【主題與背景】\\n本段落（14）反映了戰國時期諸侯國之間錯綜複雜的政治角力與軍事衝突。當時各國為了爭奪霸權或尋求生存，頻繁展開外交周旋與軍事行動。\\n\\n【詞義與名物】\\n「君臣」：指各國的統治者與輔佐之臣。\\n「戰國」：時代背景，羣雄並起。\\n\\n【縱橫機謋】\\n段落中展現了典型的戰國策士風範。他們善於揣摩人心，分析利害關係，並利用各國之間的矛盾與利益衝突，提出巧言善辯的策略，以達到保全自身或削弱敵國的政治目的。\"\n      }\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-18\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"order\": 18,\n      \"canonicalText\": \"齊聽祝弗，外周最。謂齊王曰：「逐周最、聽祝弗、相呂禮者，欲深取秦也。秦得天下，則伐齊深矣。王不如反周最，厚其禮，以合齊、楚，則秦不敢動矣。」\",\n      \"sentenceIds\": [\n        \"zhan-guo-ce_ch-1_p-18_s-1\",\n        \"zhan-guo-ce_ch-1_p-18_s-2\",\n        \"zhan-guo-ce_ch-1_p-18_s-3\",\n        \"zhan-guo-ce_ch-1_p-18_s-4\",\n        \"zhan-guo-ce_ch-1_p-18_s-5\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"經文底本\",\n          \"edition\": \"dianji.fun\",\n          \"url\": \"https://ctext.org/zhan-guo-ce/zh\"\n        },\n        {\n          \"label\": \"維基文庫《戰國策》全文\",\n          \"edition\": \"維基文庫繁體全文頁（人工開啟核實 2026-08-14）\",\n          \"url\": \"https://zh.wikisource.org/wiki/%E6%88%B0%E5%9C%8B%E7%AD%96\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"這是一段來自戰國策的歷史敘述，記載了當時各國君臣之間的政治對話與外交策略。具體描述了相關人物在面對國家危機或戰略抉擇時的應對之策（段落編號：15）。\",\n        \"analysis\": \"【主題與背景】\\n本段落（15）反映了戰國時期諸侯國之間錯綜複雜的政治角力與軍事衝突。當時各國為了爭奪霸權或尋求生存，頻繁展開外交周旋與軍事行動。\\n\\n【詞義與名物】\\n「君臣」：指各國的統治者與輔佐之臣。\\n「戰國」：時代背景，羣雄並起。\\n\\n【縱橫機謋】\\n段落中展現了典型的戰國策士風範。他們善於揣摩人心，分析利害關係，並利用各國之間的矛盾與利益衝突，提出巧言善辯的策略，以達到保全自身或削弱敵國的政治目的。\"\n      }\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-19\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"order\": 19,\n      \"canonicalText\": \"蘇厲為周最謂蘇秦曰：「君不如令王聽最，以地合於魏，趙故必怒，合於齊，是君以合齊與強楚。吏產於周，而周君重之，是君之名德立於天下也。」\",\n      \"sentenceIds\": [\n        \"zhan-guo-ce_ch-1_p-19_s-1\",\n        \"zhan-guo-ce_ch-1_p-19_s-2\",\n        \"zhan-guo-ce_ch-1_p-19_s-3\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"經文底本\",\n          \"edition\": \"dianji.fun\",\n          \"url\": \"https://ctext.org/zhan-guo-ce/zh\"\n        },\n        {\n          \"label\": \"維基文庫《戰國策》全文\",\n          \"edition\": \"維基文庫繁體全文頁（人工開啟核實 2026-08-14）\",\n          \"url\": \"https://zh.wikisource.org/wiki/%E6%88%B0%E5%9C%8B%E7%AD%96\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"這是一段來自戰國策的歷史敘述，記載了當時各國君臣之間的政治對話與外交策略。具體描述了相關人物在面對國家危機或戰略抉擇時的應對之策（段落編號：16）。\",\n        \"analysis\": \"【主題與背景】\\n本段落（16）反映了戰國時期諸侯國之間錯綜複雜的政治角力與軍事衝突。當時各國為了爭奪霸權或尋求生存，頻繁展開外交周旋與軍事行動。\\n\\n【詞義與名物】\\n「君臣」：指各國的統治者與輔佐之臣。\\n「戰國」：時代背景，羣雄並起。\\n\\n【縱橫機謋】\\n段落中展現了典型的戰國策士風範。他們善於揣摩人心，分析利害關係，並利用各國之間的矛盾與利益衝突，提出巧言善辯的策略，以達到保全自身或削弱敵國的政治目的。\"\n      }\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-20\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"order\": 20,\n      \"canonicalText\": \"謂周最曰：「仇赫之相宋，將以觀秦之應趙、宋，敗三國。三國不敗，將興趙、宋合於東方以孤秦。亦將令最居齊以合之，天下之事成矣。」\",\n      \"sentenceIds\": [\n        \"zhan-guo-ce_ch-1_p-20_s-1\",\n        \"zhan-guo-ce_ch-1_p-20_s-2\",\n        \"zhan-guo-ce_ch-1_p-20_s-3\",\n        \"zhan-guo-ce_ch-1_p-20_s-4\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"經文底本\",\n          \"edition\": \"dianji.fun\",\n          \"url\": \"https://ctext.org/zhan-guo-ce/zh\"\n        },\n        {\n          \"label\": \"維基文庫《戰國策》全文\",\n          \"edition\": \"維基文庫繁體全文頁（人工開啟核實 2026-08-14）\",\n          \"url\": \"https://zh.wikisource.org/wiki/%E6%88%B0%E5%9C%8B%E7%AD%96\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"這是一段來自戰國策的歷史敘述，記載了當時各國君臣之間的政治對話與外交策略。具體描述了相關人物在面對國家危機或戰略抉擇時的應對之策（段落編號：17）。\",\n        \"analysis\": \"【主題與背景】\\n本段落（17）反映了戰國時期諸侯國之間錯綜複雜的政治角力與軍事衝突。當時各國為了爭奪霸權或尋求生存，頻繁展開外交周旋與軍事行動。\\n\\n【詞義與名物】\\n「君臣」：指各國的統治者與輔佐之臣。\\n「戰國」：時代背景，羣雄並起。\\n\\n【縱橫機謋】\\n段落中展現了典型的戰國策士風範。他們善於揣摩人心，分析利害關係，並利用各國之間的矛盾與利益衝突，提出巧言善辯的策略，以達到保全自身或削弱敵國的政治目的。\"\n      }\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-21\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"order\": 21,\n      \"canonicalText\": \"為周最謂魏王曰：「秦知趙之難與齊戰也，將恐齊、趙之合也，必陰勁之。趙不敢戰，恐秦不己收也，必先合於齊。王不如因周最以合齊、趙，以制秦之強。」\",\n      \"sentenceIds\": [\n        \"zhan-guo-ce_ch-1_p-21_s-1\",\n        \"zhan-guo-ce_ch-1_p-21_s-2\",\n        \"zhan-guo-ce_ch-1_p-21_s-3\",\n        \"zhan-guo-ce_ch-1_p-21_s-4\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"經文底本\",\n          \"edition\": \"dianji.fun\",\n          \"url\": \"https://ctext.org/zhan-guo-ce/zh\"\n        },\n        {\n          \"label\": \"維基文庫《戰國策》全文\",\n          \"edition\": \"維基文庫繁體全文頁（人工開啟核實 2026-08-14）\",\n          \"url\": \"https://zh.wikisource.org/wiki/%E6%88%B0%E5%9C%8B%E7%AD%96\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"這是一段來自戰國策的歷史敘述，記載了當時各國君臣之間的政治對話與外交策略。具體描述了相關人物在面對國家危機或戰略抉擇時的應對之策（段落編號：18）。\",\n        \"analysis\": \"【主題與背景】\\n本段落（18）反映了戰國時期諸侯國之間錯綜複雜的政治角力與軍事衝突。當時各國為了爭奪霸權或尋求生存，頻繁展開外交周旋與軍事行動。\\n\\n【詞義與名物】\\n「君臣」：指各國的統治者與輔佐之臣。\\n「戰國」：時代背景，羣雄並起。\\n\\n【縱橫機謋】\\n段落中展現了典型的戰國策士風範。他們善於揣摩人心，分析利害關係，並利用各國之間的矛盾與利益衝突，提出巧言善辯的策略，以達到保全自身或削弱敵國的政治目的。\"\n      }\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-22\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"order\": 22,\n      \"canonicalText\": \"謂周最曰：「魏王以國與先生，貴合於秦以伐齊。薛公故主，輕忘其薛，不顧其先君之丘墓，而公獨脩齊魏之好，是公之忠於主也。」\",\n      \"sentenceIds\": [\n        \"zhan-guo-ce_ch-1_p-22_s-1\",\n        \"zhan-guo-ce_ch-1_p-22_s-2\",\n        \"zhan-guo-ce_ch-1_p-22_s-3\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"經文底本\",\n          \"edition\": \"dianji.fun\",\n          \"url\": \"https://ctext.org/zhan-guo-ce/zh\"\n        },\n        {\n          \"label\": \"維基文庫《戰國策》全文\",\n          \"edition\": \"維基文庫繁體全文頁（人工開啟核實 2026-08-14）\",\n          \"url\": \"https://zh.wikisource.org/wiki/%E6%88%B0%E5%9C%8B%E7%AD%96\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"這是一段來自戰國策的歷史敘述，記載了當時各國君臣之間的政治對話與外交策略。具體描述了相關人物在面對國家危機或戰略抉擇時的應對之策（段落編號：19）。\",\n        \"analysis\": \"【主題與背景】\\n本段落（19）反映了戰國時期諸侯國之間錯綜複雜的政治角力與軍事衝突。當時各國為了爭奪霸權或尋求生存，頻繁展開外交周旋與軍事行動。\\n\\n【詞義與名物】\\n「君臣」：指各國的統治者與輔佐之臣。\\n「戰國」：時代背景，羣雄並起。\\n\\n【縱橫機謋】\\n段落中展現了典型的戰國策士風範。他們善於揣摩人心，分析利害關係，並利用各國之間的矛盾與利益衝突，提出巧言善辯的策略，以達到保全自身或削弱敵國的政治目的。\"\n      }\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-23\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"order\": 23,\n      \"canonicalText\": \"趙取周之祭地，周君患之，告於鄭朝。鄭朝曰：「君無患也，臣請以三十金復取之。」周君予之，鄭朝獻之趙太后，言：「周君欲為太后祝壽，以三十金為太后買祭地以祀神。」太后大悅，命趙王歸周祭地。\",\n      \"sentenceIds\": [\n        \"zhan-guo-ce_ch-1_p-23_s-1\",\n        \"zhan-guo-ce_ch-1_p-23_s-2\",\n        \"zhan-guo-ce_ch-1_p-23_s-3\",\n        \"zhan-guo-ce_ch-1_p-23_s-4\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"經文底本\",\n          \"edition\": \"dianji.fun\",\n          \"url\": \"https://ctext.org/zhan-guo-ce/zh\"\n        },\n        {\n          \"label\": \"維基文庫《戰國策》全文\",\n          \"edition\": \"維基文庫繁體全文頁（人工開啟核實 2026-08-14）\",\n          \"url\": \"https://zh.wikisource.org/wiki/%E6%88%B0%E5%9C%8B%E7%AD%96\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"趙國強行侵佔了東周天子用以祭祀祖先的祭田土地，周君深感屈辱憂慮，將此事告訴了謀士鄭朝。鄭朝說：大王不必擔憂，臣只需三十鎰黃金就能替大王將祭地完整收回！周君撥給他三十金，鄭朝攜金前往趙國求見趙太后，進言道：周天子得知太后千秋聖壽，特意派遣臣奉上三十金，專門替太后購置祭祀福地以祈求神明保佑太后萬壽無疆！趙太后無比高興，隨即嚴令趙王將強佔的周室祭地全數歸還周君。\",\n        \"analysis\": \"【題解與鄭朝三十金巧取趙歸周祭地】本段為戰國智謀之絕妙典範——鄭朝避開強橫的趙王，走夫人外交路線將三十金轉化為「周君為太后祝壽買地」，促使趙太后下令完璧歸周。\\n【詞義訓詁】「祭地」：古代專門用於宗廟祭祀開銷之祭田；「鄭朝」：周室智囊策士；「太后祝壽」：借祝壽名義轉化產權屬性。\\n【高超之心理公關】鄭朝不走硬碰硬的軍政交涉，而是抓住趙太后敬神求壽的心理，將強佔土地巧妙包裝為「太后受周天子敬神福報」，令趙王無法拒絕，以極小代價（三十金）收回國家領土。\"\n      }\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-24\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"order\": 24,\n      \"canonicalText\": \"杜赫欲重景翠於周，謂周君曰：「君之國小，盡君子重寶珠玉以事諸侯，不可不察也。譬之如張羅者，張於無鳥之所，則終日無所得；張於多鳥之所，則鳥網可得也。今景翠，楚之貴臣也，周若重之，楚必德周。」周君從之。\",\n      \"sentenceIds\": [\n        \"zhan-guo-ce_ch-1_p-24_s-1\",\n        \"zhan-guo-ce_ch-1_p-24_s-2\",\n        \"zhan-guo-ce_ch-1_p-24_s-3\",\n        \"zhan-guo-ce_ch-1_p-24_s-4\",\n        \"zhan-guo-ce_ch-1_p-24_s-5\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"經文底本\",\n          \"edition\": \"dianji.fun\",\n          \"url\": \"https://ctext.org/zhan-guo-ce/zh\"\n        },\n        {\n          \"label\": \"維基文庫《戰國策》全文\",\n          \"edition\": \"維基文庫繁體全文頁（人工開啟核實 2026-08-14）\",\n          \"url\": \"https://zh.wikisource.org/wiki/%E6%88%B0%E5%9C%8B%E7%AD%96\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"謀士杜赫打算在周室抬高楚國名將景翠的地位，便對周君說：君主的國家領土狹小，傾盡君中所有珍寶重器與珍珠美玉去討好結交天下諸侯，這不可不深加審察明辨啊！這就好比張網捕鳥的獵人：如果把捕鳥網張設在沒有飛鳥的地方，整天也不會有任何收穫；如果把網張設在羣鳥聚集之處，就能網羅到無數飛鳥！如今景翠是楚國權傾朝野的核心貴臣，周室若能全力厚待重用他，楚國必定會深切感恩於周室！周君採納了這條建議。\",\n        \"analysis\": \"【題解與杜赫張羅捕鳥之喻】本段以張網捕鳥（張於多鳥之處）作精闢譬喻，論述小國有限的外交資源必須集中投資於大國最有實權之關鍵重臣。\\n【詞義訓詁】「景翠」：戰國楚國名將、柱國大將軍；「張羅者」：設網捕鳥之獵人；「多鳥之所」：權力核心集中之地。\\n【精準外交投資論】小國資源匱乏，廣撒網只會耗盡國力（終日無所得）。唯有把有限的珠玉重寶精準投向大國核心決策者（景翠），方能發揮四兩撥千斤之槓桿效應。\"\n      }\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-25\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"order\": 25,\n      \"canonicalText\": \"周共太子死，有五庶子，皆愛之，而無適立也。司馬翦謂楚王曰：「何不封公子咎，而為之請太子？」楚王使人謂周君曰：「願立公子咎為太子。」周君乃立公子咎。\",\n      \"sentenceIds\": [\n        \"zhan-guo-ce_ch-1_p-25_s-1\",\n        \"zhan-guo-ce_ch-1_p-25_s-2\",\n        \"zhan-guo-ce_ch-1_p-25_s-3\",\n        \"zhan-guo-ce_ch-1_p-25_s-4\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"經文底本\",\n          \"edition\": \"dianji.fun\",\n          \"url\": \"https://ctext.org/zhan-guo-ce/zh\"\n        },\n        {\n          \"label\": \"維基文庫《戰國策》全文\",\n          \"edition\": \"維基文庫繁體全文頁（人工開啟核實 2026-08-14）\",\n          \"url\": \"https://zh.wikisource.org/wiki/%E6%88%B0%E5%9C%8B%E7%AD%96\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"東周恭太子不幸去世，周君有五個庶出的兒子，周君對他們都很寵愛，卻遲遲未能確定立誰為太子。楚國名臣司馬翦對楚王說：大王何不主動封賞公子咎土地，並出面替他向周天子請求立為太子呢？楚王於是派遣特使前往對周君說：楚王希望立公子咎為周室太子。周君為了結好強楚，隨即正式立公子咎為太子。\",\n        \"analysis\": \"【題解與司馬翦借楚立周太子咎】本段記錄楚國大將司馬翦利用周王室立儲奪嫡僵局，主動扶植親楚公子咎為太子，展現大國干涉小國內政之手腕。\\n【詞義訓詁】「周共太子」：共通恭，東周恭太子；「無適立」：適通嫡，無嫡子可立；「公子咎」：東周公子，後即位為東周君。\\n【大國立儲干涉】周室因國力衰微，連儲君廢立亦不得不聽命於南方霸主楚國之意志，深刻展現了戰國晚期周王權名存實亡之歷史悲劇。\"\n      }\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-26\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"order\": 26,\n      \"canonicalText\": \"三國隘秦，周令其相之秦，以秦之輕也，留其行。有人謂相國曰：「秦之輕重，未可知也。秦欲知三國之情，公不如急行，見秦王而告之天下之情，秦必重公；公因調秦以和三國，是公為天下之重也。」相國乃行。\",\n      \"sentenceIds\": [\n        \"zhan-guo-ce_ch-1_p-26_s-1\",\n        \"zhan-guo-ce_ch-1_p-26_s-2\",\n        \"zhan-guo-ce_ch-1_p-26_s-3\",\n        \"zhan-guo-ce_ch-1_p-26_s-4\",\n        \"zhan-guo-ce_ch-1_p-26_s-5\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"經文底本\",\n          \"edition\": \"dianji.fun\",\n          \"url\": \"https://ctext.org/zhan-guo-ce/zh\"\n        },\n        {\n          \"label\": \"維基文庫《戰國策》全文\",\n          \"edition\": \"維基文庫繁體全文頁（人工開啟核實 2026-08-14）\",\n          \"url\": \"https://zh.wikisource.org/wiki/%E6%88%B0%E5%9C%8B%E7%AD%96\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"齊、趙、韓三國聯軍將秦軍圍困壓制在函谷關險道之中，周君命令相國出使秦國，相國因為秦國處於劣勢被列國看輕（秦之輕），便猶豫延誤滯留行程。有謀士對相國說：秦國國勢的輕重興衰，絕非眼前一時之態所能輕易判定！秦王此時最迫切想探知三國聯軍的真實軍情虛實，相公不如火速趕路啟程，面見秦王並向他詳細分析天下大勢，秦王在危難中必定對您無比敬重依賴！相公再順勢居中調停秦國與三國聯軍達成和平，這樣相公您就成為左右全天下大局的舉足輕重之人了！相國聽後頓時醒悟，立即啟程出使。\",\n        \"analysis\": \"【題解與雪中送炭成天下之重】本段記錄謀士勸告東周相國切莫「趨炎附勢、看衰秦國」，而應在秦國受困之際雪中送炭出使調停，以此攫取巨大外交威望。\\n【詞義訓詁】「隘秦」：圍困壓迫秦軍於隘道；「留其行」：拖延行程；「為天下之重」：成為左右天下和平之關鍵樞紐。\\n【逆向危機公關】真正偉大的外交家不在強者得勢時錦上添花，而在霸主受挫時提供關鍵情報與調停橋樑，以此將自身地位抬升至不可或缺之高度。\"\n      }\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-27\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"order\": 27,\n      \"canonicalText\": \"昌他亡西周，之東周，盡輸西周之情於東周。東周大喜，西周大怒。馮且曰：「臣能殺之。」君予金三十斤。馮且使人操金與書，間遺昌他於東周，書曰：「告昌他：事成，賜子金如數；事不成，殺子。」東周得書，以為昌他反，遂誅昌他。\",\n      \"sentenceIds\": [\n        \"zhan-guo-ce_ch-1_p-27_s-1\",\n        \"zhan-guo-ce_ch-1_p-27_s-2\",\n        \"zhan-guo-ce_ch-1_p-27_s-3\",\n        \"zhan-guo-ce_ch-1_p-27_s-4\",\n        \"zhan-guo-ce_ch-1_p-27_s-5\",\n        \"zhan-guo-ce_ch-1_p-27_s-6\",\n        \"zhan-guo-ce_ch-1_p-27_s-7\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"經文底本\",\n          \"edition\": \"dianji.fun\",\n          \"url\": \"https://ctext.org/zhan-guo-ce/zh\"\n        },\n        {\n          \"label\": \"維基文庫《戰國策》全文\",\n          \"edition\": \"維基文庫繁體全文頁（人工開啟核實 2026-08-14）\",\n          \"url\": \"https://zh.wikisource.org/wiki/%E6%88%B0%E5%9C%8B%E7%AD%96\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"西周國叛臣昌他叛逃出西周，投奔東周國，將西周國的所有機密軍情全盤向東周君告發透露。東周大喜過望，西周君則暴怒無比。西周謀士馮且說：臣能借刀殺人殺死昌他！西周君撥給他三十斤黃金。馮且派遣密使攜帶黃金與一封密信，祕密潛入東周故意遺落在昌他的居所旁。密信上寫道：密告昌他：內應刺殺東周大事若成，照數賞賜你黃金萬兩；事情若敗露，定當嚴懲不貸！東周官吏繳獲這封密信，東周君深信昌他是西周派來的雙料間諜臥底，隨即下令處斬誅殺了昌他。\",\n        \"analysis\": \"【題解與背景】\\n本段選自《戰國策》〈東周〉第 27 節。屬先秦兩漢思想經典，記述先賢關於立德立言、治國用兵與天地自然哲理之至要名言。\\n【詞義與名物】\\n1. 經典名句解讀：引述「昌他亡西周之東周盡輸西周之情於東周東周大……」之章法語感與對偶語氣。\\n2. 訓詁與古漢語範式：本段重點解讀「昌」、「他」、「亡」等字詞之古代漢語語意、通假字與名物制度考釋。\\n【思想與史事脈絡】\\n深刻傳達《戰國策》知行合一與經世致用之哲理觀念，彰顯傳統文化立德、立言、立功之最高追求，為後世提供極具學術價值之智慧資糧與歷史參照（段落識別標記：zhan-guo-ce_ch-1_p-27）。\"\n      }\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-28\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"order\": 28,\n      \"canonicalText\": \"昭翦與東周惡，或謂照翦曰：「為公畫陰計。」照翦曰：「何也？」「西周甚憎東周，嘗欲東周與楚惡。公不如使人謂東周君曰：『楚將伐周。』東周必因公以和於楚。是公既得德於東周，又得重於楚也。」昭翦從之。\",\n      \"sentenceIds\": [\n        \"zhan-guo-ce_ch-1_p-28_s-1\",\n        \"zhan-guo-ce_ch-1_p-28_s-2\",\n        \"zhan-guo-ce_ch-1_p-28_s-3\",\n        \"zhan-guo-ce_ch-1_p-28_s-4\",\n        \"zhan-guo-ce_ch-1_p-28_s-5\",\n        \"zhan-guo-ce_ch-1_p-28_s-6\",\n        \"zhan-guo-ce_ch-1_p-28_s-7\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"經文底本\",\n          \"edition\": \"dianji.fun\",\n          \"url\": \"https://ctext.org/zhan-guo-ce/zh\"\n        },\n        {\n          \"label\": \"維基文庫《戰國策》全文\",\n          \"edition\": \"維基文庫繁體全文頁（人工開啟核實 2026-08-14）\",\n          \"url\": \"https://zh.wikisource.org/wiki/%E6%88%B0%E5%9C%8B%E7%AD%96\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"這是一段來自戰國策的歷史敘述，記載了當時各國君臣之間的政治對話與外交策略。具體描述了相關人物在面對國家危機或戰略抉擇時的應對之策（段落編號：24）。\",\n        \"analysis\": \"【主題與背景】\\n本段落（24）反映了戰國時期諸侯國之間錯綜複雜的政治角力與軍事衝突。當時各國為了爭奪霸權或尋求生存，頻繁展開外交周旋與軍事行動。\\n\\n【詞義與名物】\\n「君臣」：指各國的統治者與輔佐之臣。\\n「戰國」：時代背景，羣雄並起。\\n\\n【縱橫機謋】\\n段落中展現了典型的戰國策士風範。他們善於揣摩人心，分析利害關係，並利用各國之間的矛盾與利益衝突，提出巧言善辯的策略，以達到保全自身或削弱敵國的政治目的。\"\n      }\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-29\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"order\": 29,\n      \"canonicalText\": \"嚴氏為賊，而陽堅與焉。道周，周君留之十四日，載以乘車駟馬而遣之。韓使人讓周，周君患之。客謂周君曰：「韓使來，君曰：『周非故留賊也。周小，力不能制，故留十四日，以待韓之使者來也。使者不來，周不敢留，故遣之。』韓必無辭以責周矣。」\",\n      \"sentenceIds\": [\n        \"zhan-guo-ce_ch-1_p-29_s-1\",\n        \"zhan-guo-ce_ch-1_p-29_s-2\",\n        \"zhan-guo-ce_ch-1_p-29_s-3\",\n        \"zhan-guo-ce_ch-1_p-29_s-4\",\n        \"zhan-guo-ce_ch-1_p-29_s-5\",\n        \"zhan-guo-ce_ch-1_p-29_s-6\",\n        \"zhan-guo-ce_ch-1_p-29_s-7\",\n        \"zhan-guo-ce_ch-1_p-29_s-8\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"經文底本\",\n          \"edition\": \"dianji.fun\",\n          \"url\": \"https://ctext.org/zhan-guo-ce/zh\"\n        },\n        {\n          \"label\": \"維基文庫《戰國策》全文\",\n          \"edition\": \"維基文庫繁體全文頁（人工開啟核實 2026-08-14）\",\n          \"url\": \"https://zh.wikisource.org/wiki/%E6%88%B0%E5%9C%8B%E7%AD%96\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"韓國大臣嚴氏家族發動叛亂作亂，俠士陽堅參與其中。陽堅逃亡途中路經東周，周君將他收留款待了整整十四天，最後用四匹馬拉的高級乘車將他隆重禮送出境。韓國得知後派遣特使前來嚴厲責問周君包庇叛賊，周君深感恐懼憂慮。一位謀士對周君說：韓國使者前來問罪時，君主就回答說：周室絕非故意收留窩藏叛賊！只因周室國小力弱，自身兵力無法將他當場逮捕制服，所以故意用酒食虛與委蛇拖延留他十四天，是為了等待韓國的追捕大軍趕來拿人啊！韓國使者遲遲不來，周室恐其發難不敢久留，這才無奈送他離境！韓國聽後就必定再也找不出任何藉口來責難周室了！\",\n        \"analysis\": \"【題解與周君留陽堅巧對韓使】本段為《戰國策・東周策》壓軸終章，記錄周君款待韓國叛將陽堅後遭韓使問罪，謀士以「示弱拖延以待韓使」之機智辭令化險為夷。\\n【詞義訓詁】「嚴氏為賊」：韓國嚴遂弒韓相俠累等政治刺殺叛亂；「陽堅」：刺客黨羽；「讓周」：責備、問罪周室；「乘車駟馬」：天子諸侯之高規格車馬。\\n【外交危機公關之極致】面對大國問罪，謀士不否認事實，而是徹底顛覆動機：將「盛情款待」狡辯為「國小力弱、委曲求全以拖延待捕」，反將責任推給韓國使者來遲，辭鋒天衣無縫，化解滅頂之災。\"\n      }\n    }\n  ],\n  \"sentences\": [\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-1_s-1\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-1\",\n      \"order\": 1,\n      \"canonicalText\": \"秦興師臨周而求九鼎，周君患之，以告顏率。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-1_s-2\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-1\",\n      \"order\": 2,\n      \"canonicalText\": \"顏率曰：「大王勿憂，臣請東借救於齊。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-1_s-3\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-1\",\n      \"order\": 3,\n      \"canonicalText\": \"」顏率至齊，謂齊王曰：「夫秦之為暴也，悉興師臨周而求九鼎。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-1_s-4\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-1\",\n      \"order\": 4,\n      \"canonicalText\": \"周之君臣內自畫計，與其與秦，不若與齊。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-1_s-5\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-1\",\n      \"order\": 5,\n      \"canonicalText\": \"割大國之名，不如救小國之德；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-1_s-6\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-1\",\n      \"order\": 6,\n      \"canonicalText\": \"得九鼎之尊，不如救周室之美。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-1_s-7\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-1\",\n      \"order\": 7,\n      \"canonicalText\": \"願大王圖之！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-1_s-8\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-1\",\n      \"order\": 8,\n      \"canonicalText\": \"」齊王大悅，發師五萬，使陳臣思將以救周，而秦兵罷。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-2_s-1\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-2\",\n      \"order\": 1,\n      \"canonicalText\": \"齊將求九鼎，周君又患之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-2_s-2\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-2\",\n      \"order\": 2,\n      \"canonicalText\": \"顏率曰：「大王勿憂，臣請東解之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-2_s-3\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-2\",\n      \"order\": 3,\n      \"canonicalText\": \"」顏率至齊，謂齊王曰：「周賴大國之義，得全社稷，願獻九鼎，不知大國何途之從以致之齊？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-2_s-4\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-2\",\n      \"order\": 4,\n      \"canonicalText\": \"」齊王曰：「寡人將寄徑於梁。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-2_s-5\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-2\",\n      \"order\": 5,\n      \"canonicalText\": \"」顏率曰：「不可。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-2_s-6\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-2\",\n      \"order\": 6,\n      \"canonicalText\": \"梁君臣欲得九鼎久矣，入梁必不出。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-2_s-7\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-2\",\n      \"order\": 7,\n      \"canonicalText\": \"」齊王曰：「寡人將寄徑於楚。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-2_s-8\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-2\",\n      \"order\": 8,\n      \"canonicalText\": \"」顏率曰：「不可。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-2_s-9\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-2\",\n      \"order\": 9,\n      \"canonicalText\": \"楚君臣欲得九鼎久矣，入楚必不出。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-2_s-10\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-2\",\n      \"order\": 10,\n      \"canonicalText\": \"」齊王曰：「寡人寄徑於齊魯之間。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-2_s-11\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-2\",\n      \"order\": 11,\n      \"canonicalText\": \"」顏率曰：「夫九鼎者，一鼎九萬人挽之，九九八十一萬人，士卒師徒之費，未易量也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-2_s-12\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-2\",\n      \"order\": 12,\n      \"canonicalText\": \"大王雖有其力，何途之從？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-2_s-13\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-2\",\n      \"order\": 13,\n      \"canonicalText\": \"」齊王乃止。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-3_s-1\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-3\",\n      \"order\": 1,\n      \"canonicalText\": \"秦攻宜陽，周君謂趙累曰：「子以為何如？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-3_s-2\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-3\",\n      \"order\": 2,\n      \"canonicalText\": \"」對曰：「宜陽必拔也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-3_s-3\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-3\",\n      \"order\": 3,\n      \"canonicalText\": \"」君曰：「宜陽城方八里，材士十萬，粟支數年，秦攻之，何以必拔？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-3_s-4\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-3\",\n      \"order\": 4,\n      \"canonicalText\": \"」對曰：「秦之巧者皆在宜陽，韓之精兵皆在宜陽，公仲之資在焉。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-3_s-5\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-3\",\n      \"order\": 5,\n      \"canonicalText\": \"今秦拔宜陽，韓必割地而和。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-3_s-6\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-3\",\n      \"order\": 6,\n      \"canonicalText\": \"周不如陰佐韓而外附秦，則周不失其重矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-3_s-7\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-3\",\n      \"order\": 7,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-4_s-1\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-4\",\n      \"order\": 1,\n      \"canonicalText\": \"東周與西周戰，韓救西周。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-4_s-2\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-4\",\n      \"order\": 2,\n      \"canonicalText\": \"為東周謂韓王曰：「西周者，故天子之國也，多名器重寶。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-4_s-3\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-4\",\n      \"order\": 3,\n      \"canonicalText\": \"案兵而勿出，可以得名器重寶於西周；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-4_s-4\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-4\",\n      \"order\": 4,\n      \"canonicalText\": \"又為東周求地於西周，東周必德韓。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-4_s-5\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-4\",\n      \"order\": 5,\n      \"canonicalText\": \"是韓一舉而得兩周之利也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-4_s-6\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-4\",\n      \"order\": 6,\n      \"canonicalText\": \"」韓王從之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-5_s-1\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-5\",\n      \"order\": 1,\n      \"canonicalText\": \"東周與西周爭，西周欲和於楚、韓。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-5_s-2\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-5\",\n      \"order\": 2,\n      \"canonicalText\": \"齊明謂東周君曰：「臣恐西周之與楚、韓寶，令之為己求地於東周也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-5_s-3\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-5\",\n      \"order\": 3,\n      \"canonicalText\": \"君不如陰使人謂楚、韓曰：『西周所以奉大國者，非真愛大國也，欲借大國之威以兼東周也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-5_s-4\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-5\",\n      \"order\": 4,\n      \"canonicalText\": \"』楚、韓必疑西周，而東周無患矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-5_s-5\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-5\",\n      \"order\": 5,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-6_s-1\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-6\",\n      \"order\": 1,\n      \"canonicalText\": \"東周欲為稻，西周不下水，東周患之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-6_s-2\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-6\",\n      \"order\": 2,\n      \"canonicalText\": \"蘇子謂東周君曰：「臣請使西周下水可乎？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-6_s-3\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-6\",\n      \"order\": 3,\n      \"canonicalText\": \"」乃往見西周之君曰：「君之計過矣！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-6_s-4\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-6\",\n      \"order\": 4,\n      \"canonicalText\": \"今不下水，所以富東周也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-6_s-5\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-6\",\n      \"order\": 5,\n      \"canonicalText\": \"東周之民皆種麥，無他種矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-6_s-6\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-6\",\n      \"order\": 6,\n      \"canonicalText\": \"君若欲害之，不若一放水，以病其所種。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-6_s-7\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-6\",\n      \"order\": 7,\n      \"canonicalText\": \"放水，東周必復種稻；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-6_s-8\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-6\",\n      \"order\": 8,\n      \"canonicalText\": \"種稻而復奪之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-6_s-9\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-6\",\n      \"order\": 9,\n      \"canonicalText\": \"若是，則東周之民可令仰西周而受命矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-6_s-10\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-6\",\n      \"order\": 10,\n      \"canonicalText\": \"」西周君曰：「善。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-6_s-11\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-6\",\n      \"order\": 11,\n      \"canonicalText\": \"」乃放水。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-6_s-12\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-6\",\n      \"order\": 12,\n      \"canonicalText\": \"蘇子得兩國之金。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-7_s-1\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-7\",\n      \"order\": 1,\n      \"canonicalText\": \"昭獻在陽翟，周君將令相國往，相國將不欲。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-7_s-2\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-7\",\n      \"order\": 2,\n      \"canonicalText\": \"蘇厲為之謂周君曰：「楚王與魏王遇也，主君令陳封之楚，令向壽之魏。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-7_s-3\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-7\",\n      \"order\": 3,\n      \"canonicalText\": \"今昭獻，天下之賢者也，主君遣相國往，是尊賢也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-7_s-4\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-7\",\n      \"order\": 4,\n      \"canonicalText\": \"相國之行，王必重之，昭獻必悅，周君之名必揚於天下。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-7_s-5\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-7\",\n      \"order\": 5,\n      \"canonicalText\": \"」周君大悅，相國遂行。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-8_s-1\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-8\",\n      \"order\": 1,\n      \"canonicalText\": \"秦假道於周以伐韓，周恐假之而惡於韓，不假而惡於秦。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-8_s-2\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-8\",\n      \"order\": 2,\n      \"canonicalText\": \"史黶謂周君曰：「君何不令人謂韓公叔曰：『秦之敢伐韓者，周信之也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-8_s-3\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-8\",\n      \"order\": 3,\n      \"canonicalText\": \"公何不與周地，周得地，必質於秦，秦必德周，周德秦，必不假道。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-8_s-4\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-8\",\n      \"order\": 4,\n      \"canonicalText\": \"』韓必與周地。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-8_s-5\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-8\",\n      \"order\": 5,\n      \"canonicalText\": \"周得韓地以謝秦，秦必喜，周無患矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-8_s-6\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-8\",\n      \"order\": 6,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-9_s-1\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-9\",\n      \"order\": 1,\n      \"canonicalText\": \"楚攻雍氏，周餦秦、韓，楚王怒周，周之君患之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-9_s-2\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-9\",\n      \"order\": 2,\n      \"canonicalText\": \"為周謂楚王曰：「以王之強而怒周，周恐，必以國合於秦、韓。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-9_s-3\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-9\",\n      \"order\": 3,\n      \"canonicalText\": \"是王為秦、韓驅周也，不如善周以疑秦、韓。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-9_s-4\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-9\",\n      \"order\": 4,\n      \"canonicalText\": \"」楚王乃解。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-10_s-1\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-10\",\n      \"order\": 1,\n      \"canonicalText\": \"周最謂石禮曰：「子何不以秦攻齊？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-10_s-2\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-10\",\n      \"order\": 2,\n      \"canonicalText\": \"臣請令齊相子，子以齊事秦，必無處矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-10_s-3\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-10\",\n      \"order\": 3,\n      \"canonicalText\": \"子因令周最居魏以共之，是天下可定也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-10_s-4\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-10\",\n      \"order\": 4,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-11_s-1\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-11\",\n      \"order\": 1,\n      \"canonicalText\": \"周相呂倉見客於周君。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-11_s-2\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-11\",\n      \"order\": 2,\n      \"canonicalText\": \"前相工師籍恐客之傷己也，因令人謂周君曰：「客者，辯士也，然而所以不可者，為其謀私也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-11_s-3\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-11\",\n      \"order\": 3,\n      \"canonicalText\": \"大王聽之，必有後悔。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-11_s-4\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-11\",\n      \"order\": 4,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-12_s-1\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-12\",\n      \"order\": 1,\n      \"canonicalText\": \"周文君免士工師籍，相呂倉，國人不說也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-12_s-2\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-12\",\n      \"order\": 2,\n      \"canonicalText\": \"君有閔閔之心。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-12_s-3\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-12\",\n      \"order\": 3,\n      \"canonicalText\": \"謂周文君曰：「國必有誹譽，忠臣令誹在己，譽在君。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-12_s-4\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-12\",\n      \"order\": 4,\n      \"canonicalText\": \"今呂倉相而民不說，是倉代君受誹也，君何患焉？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-12_s-5\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-12\",\n      \"order\": 5,\n      \"canonicalText\": \"」文君乃安。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-13_s-1\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-13\",\n      \"order\": 1,\n      \"canonicalText\": \"溫人之周，周不納。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-13_s-2\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-13\",\n      \"order\": 2,\n      \"canonicalText\": \"「客即？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-13_s-3\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-13\",\n      \"order\": 3,\n      \"canonicalText\": \"」對曰：「主人也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-13_s-4\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-13\",\n      \"order\": 4,\n      \"canonicalText\": \"」問其巷而不知也，使因囚之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-13_s-5\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-13\",\n      \"order\": 5,\n      \"canonicalText\": \"君使人問之曰：「子非周人，何謂主人？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-13_s-6\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-13\",\n      \"order\": 6,\n      \"canonicalText\": \"」對曰：「臣讀《詩》曰：『普天之下，莫非王土；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-13_s-7\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-13\",\n      \"order\": 7,\n      \"canonicalText\": \"率土之濱，莫非王臣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-13_s-8\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-13\",\n      \"order\": 8,\n      \"canonicalText\": \"』今周君王天下，臣固周君之民也，安得為客？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-13_s-9\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-13\",\n      \"order\": 9,\n      \"canonicalText\": \"」周君悅而釋之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-14_s-1\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-14\",\n      \"order\": 1,\n      \"canonicalText\": \"或為周最謂金投曰：「秦以周最之齊疑天下，而又知趙之難子齊人戰，恐齊、韓之合，必先合於秦。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-14_s-2\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-14\",\n      \"order\": 2,\n      \"canonicalText\": \"秦、齊合，則趙、魏必受其制。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-14_s-3\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-14\",\n      \"order\": 3,\n      \"canonicalText\": \"公不如因而結周最於齊，齊必重公。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-14_s-4\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-14\",\n      \"order\": 4,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-15_s-1\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-15\",\n      \"order\": 1,\n      \"canonicalText\": \"周最謂金投曰：「公負令秦與強齊戰。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-15_s-2\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-15\",\n      \"order\": 2,\n      \"canonicalText\": \"戰勝，秦且收齊而封之，使無多割，而聽天下之戰；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-15_s-3\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-15\",\n      \"order\": 3,\n      \"canonicalText\": \"不勝，國大危，天下必乘其弊而攻秦。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-15_s-4\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-15\",\n      \"order\": 4,\n      \"canonicalText\": \"公不若令和秦於齊，使天下無患。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-15_s-5\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-15\",\n      \"order\": 5,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-16_s-1\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-16\",\n      \"order\": 1,\n      \"canonicalText\": \"石行秦謂大梁造曰：「欲決霸王之名，不如備兩周辯知之士。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-16_s-2\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-16\",\n      \"order\": 2,\n      \"canonicalText\": \"」謂周君曰：「君不如令辯知之士，為君行說天下，則周重矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-16_s-3\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-16\",\n      \"order\": 3,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-17_s-1\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-17\",\n      \"order\": 1,\n      \"canonicalText\": \"謂薛公曰：「周最於齊王也而逐之，聽祝弗，相呂禮者，欲取秦。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-17_s-2\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-17\",\n      \"order\": 2,\n      \"canonicalText\": \"秦、齊合，弗與禮重矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-17_s-3\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-17\",\n      \"order\": 3,\n      \"canonicalText\": \"有周齊，秦必輕齊。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-17_s-4\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-17\",\n      \"order\": 4,\n      \"canonicalText\": \"公不如令齊王復用周最，以制秦謀。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-17_s-5\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-17\",\n      \"order\": 5,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-18_s-1\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-18\",\n      \"order\": 1,\n      \"canonicalText\": \"齊聽祝弗，外周最。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-18_s-2\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-18\",\n      \"order\": 2,\n      \"canonicalText\": \"謂齊王曰：「逐周最、聽祝弗、相呂禮者，欲深取秦也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-18_s-3\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-18\",\n      \"order\": 3,\n      \"canonicalText\": \"秦得天下，則伐齊深矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-18_s-4\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-18\",\n      \"order\": 4,\n      \"canonicalText\": \"王不如反周最，厚其禮，以合齊、楚，則秦不敢動矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-18_s-5\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-18\",\n      \"order\": 5,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-19_s-1\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-19\",\n      \"order\": 1,\n      \"canonicalText\": \"蘇厲為周最謂蘇秦曰：「君不如令王聽最，以地合於魏，趙故必怒，合於齊，是君以合齊與強楚。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-19_s-2\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-19\",\n      \"order\": 2,\n      \"canonicalText\": \"吏產於周，而周君重之，是君之名德立於天下也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-19_s-3\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-19\",\n      \"order\": 3,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-20_s-1\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-20\",\n      \"order\": 1,\n      \"canonicalText\": \"謂周最曰：「仇赫之相宋，將以觀秦之應趙、宋，敗三國。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-20_s-2\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-20\",\n      \"order\": 2,\n      \"canonicalText\": \"三國不敗，將興趙、宋合於東方以孤秦。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-20_s-3\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-20\",\n      \"order\": 3,\n      \"canonicalText\": \"亦將令最居齊以合之，天下之事成矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-20_s-4\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-20\",\n      \"order\": 4,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-21_s-1\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-21\",\n      \"order\": 1,\n      \"canonicalText\": \"為周最謂魏王曰：「秦知趙之難與齊戰也，將恐齊、趙之合也，必陰勁之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-21_s-2\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-21\",\n      \"order\": 2,\n      \"canonicalText\": \"趙不敢戰，恐秦不己收也，必先合於齊。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-21_s-3\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-21\",\n      \"order\": 3,\n      \"canonicalText\": \"王不如因周最以合齊、趙，以制秦之強。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-21_s-4\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-21\",\n      \"order\": 4,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-22_s-1\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-22\",\n      \"order\": 1,\n      \"canonicalText\": \"謂周最曰：「魏王以國與先生，貴合於秦以伐齊。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-22_s-2\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-22\",\n      \"order\": 2,\n      \"canonicalText\": \"薛公故主，輕忘其薛，不顧其先君之丘墓，而公獨脩齊魏之好，是公之忠於主也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-22_s-3\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-22\",\n      \"order\": 3,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-23_s-1\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-23\",\n      \"order\": 1,\n      \"canonicalText\": \"趙取周之祭地，周君患之，告於鄭朝。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-23_s-2\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-23\",\n      \"order\": 2,\n      \"canonicalText\": \"鄭朝曰：「君無患也，臣請以三十金復取之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-23_s-3\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-23\",\n      \"order\": 3,\n      \"canonicalText\": \"」周君予之，鄭朝獻之趙太后，言：「周君欲為太后祝壽，以三十金為太后買祭地以祀神。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-23_s-4\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-23\",\n      \"order\": 4,\n      \"canonicalText\": \"」太后大悅，命趙王歸周祭地。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-24_s-1\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-24\",\n      \"order\": 1,\n      \"canonicalText\": \"杜赫欲重景翠於周，謂周君曰：「君之國小，盡君子重寶珠玉以事諸侯，不可不察也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-24_s-2\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-24\",\n      \"order\": 2,\n      \"canonicalText\": \"譬之如張羅者，張於無鳥之所，則終日無所得；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-24_s-3\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-24\",\n      \"order\": 3,\n      \"canonicalText\": \"張於多鳥之所，則鳥網可得也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-24_s-4\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-24\",\n      \"order\": 4,\n      \"canonicalText\": \"今景翠，楚之貴臣也，周若重之，楚必德周。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-24_s-5\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-24\",\n      \"order\": 5,\n      \"canonicalText\": \"」周君從之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-25_s-1\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-25\",\n      \"order\": 1,\n      \"canonicalText\": \"周共太子死，有五庶子，皆愛之，而無適立也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-25_s-2\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-25\",\n      \"order\": 2,\n      \"canonicalText\": \"司馬翦謂楚王曰：「何不封公子咎，而為之請太子？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-25_s-3\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-25\",\n      \"order\": 3,\n      \"canonicalText\": \"」楚王使人謂周君曰：「願立公子咎為太子。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-25_s-4\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-25\",\n      \"order\": 4,\n      \"canonicalText\": \"」周君乃立公子咎。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-26_s-1\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-26\",\n      \"order\": 1,\n      \"canonicalText\": \"三國隘秦，周令其相之秦，以秦之輕也，留其行。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-26_s-2\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-26\",\n      \"order\": 2,\n      \"canonicalText\": \"有人謂相國曰：「秦之輕重，未可知也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-26_s-3\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-26\",\n      \"order\": 3,\n      \"canonicalText\": \"秦欲知三國之情，公不如急行，見秦王而告之天下之情，秦必重公；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-26_s-4\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-26\",\n      \"order\": 4,\n      \"canonicalText\": \"公因調秦以和三國，是公為天下之重也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-26_s-5\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-26\",\n      \"order\": 5,\n      \"canonicalText\": \"」相國乃行。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-27_s-1\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-27\",\n      \"order\": 1,\n      \"canonicalText\": \"昌他亡西周，之東周，盡輸西周之情於東周。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-27_s-2\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-27\",\n      \"order\": 2,\n      \"canonicalText\": \"東周大喜，西周大怒。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-27_s-3\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-27\",\n      \"order\": 3,\n      \"canonicalText\": \"馮且曰：「臣能殺之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-27_s-4\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-27\",\n      \"order\": 4,\n      \"canonicalText\": \"」君予金三十斤。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-27_s-5\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-27\",\n      \"order\": 5,\n      \"canonicalText\": \"馮且使人操金與書，間遺昌他於東周，書曰：「告昌他：事成，賜子金如數；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-27_s-6\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-27\",\n      \"order\": 6,\n      \"canonicalText\": \"事不成，殺子。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-27_s-7\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-27\",\n      \"order\": 7,\n      \"canonicalText\": \"」東周得書，以為昌他反，遂誅昌他。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-28_s-1\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-28\",\n      \"order\": 1,\n      \"canonicalText\": \"昭翦與東周惡，或謂照翦曰：「為公畫陰計。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-28_s-2\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-28\",\n      \"order\": 2,\n      \"canonicalText\": \"」照翦曰：「何也？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-28_s-3\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-28\",\n      \"order\": 3,\n      \"canonicalText\": \"」「西周甚憎東周，嘗欲東周與楚惡。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-28_s-4\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-28\",\n      \"order\": 4,\n      \"canonicalText\": \"公不如使人謂東周君曰：『楚將伐周。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-28_s-5\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-28\",\n      \"order\": 5,\n      \"canonicalText\": \"』東周必因公以和於楚。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-28_s-6\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-28\",\n      \"order\": 6,\n      \"canonicalText\": \"是公既得德於東周，又得重於楚也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-28_s-7\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-28\",\n      \"order\": 7,\n      \"canonicalText\": \"」昭翦從之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-29_s-1\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-29\",\n      \"order\": 1,\n      \"canonicalText\": \"嚴氏為賊，而陽堅與焉。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-29_s-2\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-29\",\n      \"order\": 2,\n      \"canonicalText\": \"道周，周君留之十四日，載以乘車駟馬而遣之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-29_s-3\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-29\",\n      \"order\": 3,\n      \"canonicalText\": \"韓使人讓周，周君患之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-29_s-4\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-29\",\n      \"order\": 4,\n      \"canonicalText\": \"客謂周君曰：「韓使來，君曰：『周非故留賊也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-29_s-5\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-29\",\n      \"order\": 5,\n      \"canonicalText\": \"周小，力不能制，故留十四日，以待韓之使者來也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-29_s-6\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-29\",\n      \"order\": 6,\n      \"canonicalText\": \"使者不來，周不敢留，故遣之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-29_s-7\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-29\",\n      \"order\": 7,\n      \"canonicalText\": \"』韓必無辭以責周矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"zhan-guo-ce_ch-1_p-29_s-8\",\n      \"workId\": \"zhan-guo-ce\",\n      \"chapterId\": \"zhan-guo-ce_ch-1\",\n      \"passageId\": \"zhan-guo-ce_ch-1_p-29\",\n      \"order\": 8,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    }\n  ]\n}") as WorkBundle
